func TestEnumListConversationsMessagesRequestUnread(t *testing.T) {
	t.Run("NewFromString_true", func(t *testing.T) {
		t.Parallel()
		val, err := NewListConversationsMessagesRequestUnreadFromString("true")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ListConversationsMessagesRequestUnread("true"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_false", func(t *testing.T) {
		t.Parallel()
		val, err := NewListConversationsMessagesRequestUnreadFromString("false")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ListConversationsMessagesRequestUnread("false"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewListConversationsMessagesRequestUnreadFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewListConversationsMessagesRequestUnreadFromString("true")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}
